ENV_NAME="$(basename "$SCRIPT_DIR")"
SAFE_PROJECT="$(echo "$PROJECT_KEY" | sed "s/[^a-zA-Z0-9]/_/g")"
SAFE_ENV="$(echo "$ENV_NAME" | sed "s/[^a-zA-Z0-9]/_/g")"
