load_state() { local v="$1"; local f="${PROJECT_STATE}/${v}"; [ -f "$f" ] && eval "${v}="$(cat "$f")""; }
save_state() { local v="$1"; shift; echo "$*" > "${PROJECT_STATE}/${v}"; }

